export interface INISection {
  id: string;
  name: string;
  category: 'main' | 'signature' | 'logging' | 'console' | 'proxy' | 'mcsettings' | 'chatbot' | 'other';
  categoryLabel: string;
  description?: string;
  settings: INISetting[];
}

// Map section name to friendly category
export function getSectionCategory(sectionName: string): {
  category: INISection['category'];
  categoryLabel: string;
} {
  const name = sectionName.toLowerCase();
  if (name.startsWith('main') || name === 'head' || name.startsWith('appvar')) {
    return { category: 'main', categoryLabel: '🌐 Cấu Hình Chính & Máy Chủ (Main & Server)' };
  }
  if (name.startsWith('signature')) {
    return { category: 'signature', categoryLabel: '🔑 Chữ Ký & Bảo Mật (Signature)' };
  }
  if (name.startsWith('logging')) {
    return { category: 'logging', categoryLabel: '📜 Nhật Ký & Debug (Logging)' };
  }
  if (name.startsWith('console')) {
    return { category: 'console', categoryLabel: '🖥️ Giao Diện Console & Minimap' };
  }
  if (name.startsWith('proxy')) {
    return { category: 'proxy', categoryLabel: '🔌 Mạng & Proxy' };
  }
  if (name.startsWith('mcsettings') || name.startsWith('chatformat')) {
    return { category: 'mcsettings', categoryLabel: '🎮 Cài Đặt Minecraft Client' };
  }
  if (name.startsWith('chatbot')) {
    return { category: 'chatbot', categoryLabel: '🤖 ChatBots & Tự Động Hóa (Auto Bots)' };
  }
  return { category: 'other', categoryLabel: '⚙️ Cấu Hình Khác (Other)' };
}

// Known enums for specific keys
const KNOWN_ENUMS: Record<string, string[]> = {
  MinecraftVersion: [
    'auto',
    '1.21.4', '1.21.3', '1.21.1', '1.21',
    '1.20.6', '1.20.5', '1.20.4', '1.20.3', '1.20.2', '1.20.1', '1.20',
    '1.19.4', '1.19.3', '1.19.2', '1.19.1', '1.19',
    '1.18.2', '1.18.1', '1.18',
    '1.17.1', '1.17',
    '1.16.5', '1.16.4', '1.16.3', '1.16.2', '1.16.1', '1.16',
    '1.15.2', '1.15.1', '1.15',
    '1.14.4', '1.14.3', '1.14.2', '1.14.1', '1.14',
    '1.13.2', '1.13.1', '1.13',
    '1.12.2', '1.12.1', '1.12',
    '1.11.2', '1.11',
    '1.10.2', '1.10',
    '1.9.4', '1.9.2', '1.9',
    '1.8.9', '1.8.8', '1.8',
    '1.7.10', '1.7.2', '1.6.4', '1.5.2', '1.4.6'
  ],
  AccountType: ['mojang', 'microsoft', 'yggdrasil'],
  Method: ['mcc', 'browser'],
  InternalCmdChar: ['none', 'slash', 'backslash'],
  EnableForge: ['auto', 'no', 'force'],
  BrandInfo: ['mcc', 'vanilla', 'none'],
  SessionCache: ['none', 'memory', 'disk'],
  ProfileKeyCache: ['none', 'memory', 'disk'],
  ResolveSrvRecords: ['no', 'fast', 'yes'],
  FilterMode: ['disable', 'blacklist', 'whitelist'],
  ConsoleMode: ['classic', 'tui'],
  ConsoleColorMode: ['disable', 'legacy_4bit', 'vt100_4bit', 'vt100_8bit', 'vt100_24bit'],
  Position: ['top_left', 'top_right', 'center', 'bottom_left', 'bottom_right'],
  CaveMode: ['auto', 'on', 'off'],
  Proxy_Type: ['HTTP', 'SOCKS4', 'SOCKS4a', 'SOCKS5'],
  Difficulty: ['peaceful', 'easy', 'normal', 'difficult'],
  ChatMode: ['enabled', 'commands', 'disabled'],
  MainHand: ['left', 'right'],
  Mode: ['single', 'multi', 'include', 'exclude', 'everything', 'lookat', 'fixedpos', 'both'],
  Priority: ['health', 'distance'],
  Interaction: ['Attack', 'Interact', 'InteractAt'],
  List_Mode: ['whitelist', 'blacklist'],
  List_Type: ['whitelist', 'blacklist'],
  OnFailure: ['abort', 'wait'],
  Location_Order: ['distance', 'index'],
};

function getKnownEnumOptions(rawKey: string): string[] | undefined {
  const matchKey = Object.keys(KNOWN_ENUMS).find((k) => k.toLowerCase() === rawKey.toLowerCase());
  return matchKey ? KNOWN_ENUMS[matchKey] : undefined;
}

// Parse raw INI text into structured sections while preserving comments
export function parseIniToSections(rawIni: string): INISection[] {
  const lines = rawIni.split(/\r?\n/);
  const sections: INISection[] = [];
  let currentSection: INISection | null = null;
  let accumulatedComment = '';

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();

    // Skip empty lines
    if (!line) {
      accumulatedComment = '';
      continue;
    }

    // Comment line
    if (line.startsWith('#') || line.startsWith(';')) {
      const commentText = line.replace(/^[#;]\s*/, '').trim();
      if (!commentText.startsWith('===') && !commentText.startsWith('---')) {
        accumulatedComment = accumulatedComment ? `${accumulatedComment} ${commentText}` : commentText;
      }
      continue;
    }

    // Section header line e.g. [Main.General] or [[ChatBot.AutoCraft.Recipes]]
    const sectionMatch = line.match(/^\[{1,2}([^\]]+)\]{1,2}$/);
    if (sectionMatch) {
      const sectionName = sectionMatch[1].trim();
      const { category, categoryLabel } = getSectionCategory(sectionName);

      currentSection = {
        id: `sec-${sectionName.replace(/[^a-zA-Z0-9]/g, '_')}-${i}`,
        name: sectionName,
        category,
        categoryLabel,
        description: accumulatedComment || undefined,
        settings: [],
      };
      sections.push(currentSection);
      accumulatedComment = '';
      continue;
    }

    // Key-Value line e.g. Key = Value # comment
    const kvMatch = line.match(/^([a-zA-Z0-9_\-.\s"']+)=\s*(.*)$/);
    if (kvMatch && currentSection) {
      let rawKey = kvMatch[1].trim();
      let rawValAndComment = kvMatch[2].trim();

      // Clean quotes from key if present
      if ((rawKey.startsWith('"') && rawKey.endsWith('"')) || (rawKey.startsWith("'") && rawKey.endsWith("'"))) {
        rawKey = rawKey.slice(1, -1);
      }

      // Extract inline comment if any
      let inlineComment = '';
      let rawVal = rawValAndComment;

      // Handle comments preceded by # or ;
      const hashIdx = rawValAndComment.indexOf('#');
      if (hashIdx !== -1) {
        inlineComment = rawValAndComment.slice(hashIdx + 1).trim();
        rawVal = rawValAndComment.slice(0, hashIdx).trim();
      }

      const combinedComment = [accumulatedComment, inlineComment].filter(Boolean).join(' - ');
      accumulatedComment = '';

      // Determine value type & parsed value
      let parsedValue: any = rawVal;
      let type: INISetting['type'] = 'string';

      // Boolean
      if (rawVal.toLowerCase() === 'true' || rawVal.toLowerCase() === 'false') {
        type = 'boolean';
        parsedValue = rawVal.toLowerCase() === 'true';
      }
      // Number
      else if (!isNaN(Number(rawVal)) && rawVal !== '') {
        type = 'number';
        parsedValue = Number(rawVal);
      }
      // Array e.g. [ "a", "b" ]
      else if (rawVal.startsWith('[') && rawVal.endsWith(']')) {
        type = 'array';
        try {
          // Parse array items
          const inner = rawVal.slice(1, -1).trim();
          if (!inner) {
            parsedValue = [];
          } else {
            parsedValue = inner
              .split(',')
              .map((item) => item.trim())
              .filter(Boolean)
              .map((item) => item.replace(/^["']|["']$/g, ''));
          }
        } catch {
          parsedValue = [];
        }
      }
      // Inline object e.g. { Login = "geasf", Password = "-" } or { min = 60, max = 60 }
      else if (rawVal.startsWith('{') && rawVal.endsWith('}')) {
        type = 'object';
        parsedValue = rawVal;
      }
      // Enum check
      else {
        // Strip outer quotes if string
        if ((rawVal.startsWith('"') && rawVal.endsWith('"')) || (rawVal.startsWith("'") && rawVal.endsWith("'"))) {
          parsedValue = rawVal.slice(1, -1);
        }
        const opts = getKnownEnumOptions(rawKey);
        if (opts) {
          type = 'enum';
        }
      }

      currentSection.settings.push({
        key: rawKey,
        value: parsedValue,
        rawValue: rawVal,
        type,
        comment: combinedComment || undefined,
        options: getKnownEnumOptions(rawKey),
      });
    }
  }

  return sections;
}

// Serialize structured sections back to raw INI text
export function serializeSectionsToIni(sections: INISection[], originalRawIni?: string): string {
  // If we have sections, build a clean INI text
  const outputLines: string[] = [];
  outputLines.push('# Startup Config File (Generated & Updated by MCC Web Engine)');
  outputLines.push('# Documentation: https://mccteam.github.io/g/conf.html\n');

  for (const sec of sections) {
    if (sec.settings.length === 0 && !sec.description) continue;

    outputLines.push(`[${sec.name}]`);

    for (const setting of sec.settings) {
      let valStr = '';

      if (setting.type === 'boolean') {
        valStr = setting.value ? 'true' : 'false';
      } else if (setting.type === 'number') {
        valStr = String(setting.value);
      } else if (setting.type === 'array') {
        if (Array.isArray(setting.value)) {
          valStr = `[ ${setting.value.map((v) => `"${v}"`).join(', ')} ]`;
        } else {
          valStr = String(setting.value);
        }
      } else if (setting.type === 'object') {
        valStr = String(setting.value);
      } else {
        // String or enum
        const strVal = String(setting.value);
        // Avoid double quoting if already quoted or object format
        if (strVal.startsWith('{') || strVal.startsWith('[')) {
          valStr = strVal;
        } else {
          valStr = `"${strVal}"`;
        }
      }

      // Format key with proper spacing
      let keyFormatted = setting.key;
      if (keyFormatted.includes(' ')) {
        keyFormatted = `"${keyFormatted}"`;
      }

      let line = `${keyFormatted} = ${valStr}`;
      if (setting.comment) {
        line = `${line.padEnd(45)} # ${setting.comment}`;
      }
      outputLines.push(line);
    }

    outputLines.push(''); // Empty separator line between sections
  }

  return outputLines.join('\n');
}

export interface INIRepairResult {
  repairedIni: string;
  fixCount: number;
  logs: string[];
}

// Auto-repair common syntax errors in MinecraftClient.ini
export function fixAndSanitizeIniContent(rawIni: string): INIRepairResult {
  const lines = rawIni.split(/\r?\n/);
  const repairedLines: string[] = [];
  let fixCount = 0;
  const logs: string[] = [];

  /** Escape unescaped backslashes inside a quoted value so MCC's ini parser never breaks
      (fixes "Found an invalid escape sequence '\\.'" errors from pasted Windows paths etc.) */
  const escapeBackslashes = (quoted: string): string => {
    if (!quoted.includes('\\')) return quoted;
    const quoteChar = quoted[0];
    const inner = quoted.slice(1, -1);
    const escaped = inner.replace(/\\(?!\\)/g, '\\\\');
    return quoteChar + escaped + quoteChar;
  };

  for (let i = 0; i < lines.length; i++) {
    let line = lines[i];
    const trimmed = line.trim();

    // Skip empty lines or pure comment lines
    if (!trimmed || trimmed.startsWith('#') || trimmed.startsWith(';')) {
      repairedLines.push(line);
      continue;
    }

    // 1. Fix Section Headers e.g. [ChatBot.AutoRespond (missing ']') or [ChatBot.AutoRespond.]
    if (trimmed.startsWith('[')) {
      // Check if missing closing bracket
      if (!trimmed.includes(']')) {
        let name = trimmed.replace(/^\[+/, '').trim();
        name = name.replace(/\.+$|^\.+/g, ''); // strip trailing or leading dots
        line = `[${name}]`;
        fixCount++;
        logs.push(`Dòng ${i + 1}: Thêm dấu ']' còn thiếu cho section header -> [${name}]`);
      } else {
        // Has both brackets, clean up extra dots inside or outside e.g. [ChatBot.AutoRespond.]
        const match = line.match(/^(\s*)\[+([^\]]+)\]+(\s*)$/);
        if (match) {
          const indent = match[1];
          let secName = match[2].trim();
          const cleanName = secName.replace(/^\.+|\.+$|(?<=\.)\.+/g, ''); // remove leading/trailing or double dots
          if (secName !== cleanName) {
            line = `${indent}[${cleanName}]`;
            fixCount++;
            logs.push(`Dòng ${i + 1}: Sửa tên section header -> [${cleanName}]`);
          }
        }
      }
      repairedLines.push(line);
      continue;
    }

    // 2. Fix Inline Object Syntax e.g. Server = { Host = 127.0.0.1, Port = 25565 } or Account = { Login = geasf }
    if (trimmed.includes('{') && trimmed.includes('}')) {
      const kvMatch = line.match(/^(\s*)([a-zA-Z0-9_\-.\s"']+)=\s*\{(.*)\}(\s*#.*)?$/);
      if (kvMatch) {
        const indent = kvMatch[1];
        const key = kvMatch[2].trim();
        const inner = kvMatch[3];
        const comment = kvMatch[4] || '';

        // Process inner properties e.g. Host = 127.0.0.1, Port = 25565
        const props = inner.split(',').map((p) => p.trim()).filter(Boolean);
        let innerModified = false;

        const fixedProps = props.map((prop) => {
          const propMatch = prop.match(/^([a-zA-Z0-9_\-]+)\s*=\s*(.*)$/);
          if (propMatch) {
            const pKey = propMatch[1].trim();
            let pVal = propMatch[2].trim();

            // Unquote erroneously quoted empty array strings e.g. Times = "[ ]"
            if (pVal === '"[ ]"' || pVal === "'[ ]'") {
              pVal = '[ ]';
              innerModified = true;
            } else if (
              !pVal.startsWith('"') &&
              !pVal.startsWith("'") &&
              !pVal.startsWith('[') &&
              pVal.toLowerCase() !== 'true' &&
              pVal.toLowerCase() !== 'false' &&
              isNaN(Number(pVal))
            ) {
              pVal = `"${pVal}"`;
              innerModified = true;
            }

            // Escape unescaped backslashes in quoted values (fixes "\\. invalid escape sequence")
            if (pVal.startsWith('"') && pVal.includes('\\')) {
              const safeVal = escapeBackslashes(pVal);
              if (safeVal !== pVal) {
                pVal = safeVal;
                innerModified = true;
              }
            }
            return `${pKey} = ${pVal}`;
          }
          return prop;
        });

        if (innerModified) {
          line = `${indent}${key} = { ${fixedProps.join(', ')} }${comment}`;
          fixCount++;
          logs.push(`Dòng ${i + 1}: Sửa dấu ngoặc kép cho đối tượng ${key} -> { ${fixedProps.join(', ')} }`);
        }
      }
      repairedLines.push(line);
      continue;
    }

    // 3. Fix Unquoted Strings or TOML Array Keys e.g. ChatBot, Matches_File = matches.ini, ServerIP = 127.0.0.1
    const kvMatch = line.match(/^(\s*)([a-zA-Z0-9_\-.]+)\s*=\s*(.*)$/);
    if (kvMatch) {
      const indent = kvMatch[1];
      const key = kvMatch[2].trim();
      let valAndComment = kvMatch[3].trim();

      // Separate inline comment
      let val = valAndComment;
      let comment = '';
      const hashIdx = valAndComment.indexOf('#');
      const semiIdx = valAndComment.indexOf(';');
      const commentIdx = hashIdx !== -1 && semiIdx !== -1 ? Math.min(hashIdx, semiIdx) : (hashIdx !== -1 ? hashIdx : semiIdx);

      if (commentIdx !== -1) {
        val = valAndComment.slice(0, commentIdx).trim();
        comment = ' ' + valAndComment.slice(commentIdx).trim();
      }

      // Check if key is a known TOML Array property (e.g. ChatBot, Bots, BotOwners, Matches, Excludes)
      const ARRAY_KEYS = ['chatbot', 'bots', 'botowners', 'matches', 'excludes', 'packetdebugexclusions', 'entites_list', 'script', 'commands'];
      const isArrayKey = ARRAY_KEYS.includes(key.toLowerCase());

      if (isArrayKey) {
        // If it's already formatted as a TOML array e.g. [ "AutoRespond" ], do not touch
        if (val.startsWith('[') && val.endsWith(']')) {
          repairedLines.push(line);
          continue;
        }

        // Format unquoted list/string into a TOML Array e.g. ChatBot = [ "AutoRespond" ]
        const items = val
          .split(',')
          .map((s) => s.trim().replace(/^["']|["']$/g, ''))
          .filter(Boolean);

        const newArrVal = items.length > 0 ? `[ ${items.map((it) => `"${it}"`).join(', ')} ]` : '[ ]';
        line = `${indent}${key} = ${newArrVal}${comment}`;
        fixCount++;
        logs.push(`Dòng ${i + 1}: Chuyển ${key} thành Mảng TOML (Array) chuẩn -> ${newArrVal}`);
        repairedLines.push(line);
        continue;
      }

      // Check if general string value needs quoting
      if (
        val &&
        !val.startsWith('"') &&
        !val.startsWith("'") &&
        !val.startsWith('[') &&
        !val.startsWith('{') &&
        val.toLowerCase() !== 'true' &&
        val.toLowerCase() !== 'false'
      ) {
        // Check if pure integer or single decimal float (e.g. 25565 or 1.0)
        const isPureNumber = !isNaN(Number(val)) && !val.includes('..') && !/^[0-9]+\.[0-9]+\.[0-9]+/.test(val);

        if (!isPureNumber) {
          const newVal = `"${val}"`;
          line = `${indent}${key} = ${newVal}${comment}`;
          fixCount++;
          logs.push(`Dòng ${i + 1}: Thêm dấu ngoặc kép cho ${key} = ${newVal}`);
        }
      }

      // Escape unescaped backslashes inside already-quoted values (fixes "\\. invalid escape sequence")
      if (val.startsWith('"') && val.endsWith('"') && val.includes('\\')) {
        const safeVal = escapeBackslashes(val);
        if (safeVal !== val) {
          line = `${indent}${key} = ${safeVal}${comment}`;
          fixCount++;
          logs.push(`Dòng ${i + 1}: Escape dấu gạch chéo ngược trong ${key} -> ${safeVal}`);
        }
      }
    }

    repairedLines.push(line);
  }

  return {
    repairedIni: repairedLines.join('\n'),
    fixCount,
    logs,
  };
}

/**
 * Minecraft Chat Color and Format Parser
 * Converts Mineflayer chat objects, string with § or & color codes, or JSON chat components to HTML/Spans.
 * Supports full 1.16+ RGB Hex codes (&#RRGGBB, §x§1§2§3§4§5§6) and named color maps.
 */

const COLOR_MAP: Record<string, string> = {
  '0': '#000000', // Black
  '1': '#0000AA', // Dark Blue
  '2': '#00AA00', // Dark Green
  '3': '#00AAAA', // Dark Aqua
  '4': '#AA0000', // Dark Red
  '5': '#AA00AA', // Dark Purple
  '6': '#FFAA00', // Gold
  '7': '#AAAAAA', // Gray
  '8': '#555555', // Dark Gray
  '9': '#5555FF', // Blue
  'a': '#55FF55', // Green
  'b': '#55FFFF', // Aqua
  'c': '#FF5555', // Red
  'd': '#FF55FF', // Light Purple
  'e': '#FFFF55', // Yellow
  'f': '#FFFFFF', // White
  // Named colors in JSON chat
  black: '#000000',
  dark_blue: '#0000AA',
  dark_green: '#00AA00',
  dark_aqua: '#00AAAA',
  dark_red: '#AA0000',
  dark_purple: '#AA00AA',
  gold: '#FFAA00',
  gray: '#AAAAAA',
  dark_gray: '#555555',
  blue: '#5555FF',
  green: '#55FF55',
  aqua: '#55FFFF',
  red: '#FF5555',
  light_purple: '#FF55FF',
  yellow: '#FFFF55',
  white: '#FFFFFF',
  reset: '#FFFFFF',
};

export interface ChatPiece {
  text: string;
  color?: string;
  bold?: boolean;
  italic?: boolean;
  underlined?: boolean;
  strikethrough?: boolean;
  obfuscated?: boolean;
}

export function parseMcColorCodes(input: string): ChatPiece[] {
  if (!input) return [];

  // Pre-process §x§R§R§G§G§B§B or &x&R&R&G&G&B&B legacy hex formats into &#RRGGBB
  let normalized = input.replace(/[§&]x([§&][0-9a-fA-F]){6}/gi, (match) => {
    const chars = match.replace(/[§&]x/i, '').replace(/[§&]/g, '');
    return `&#${chars}`;
  });

  const pieces: ChatPiece[] = [];
  const regex = /(?:[§&]([0-9a-fk-or]))|(?:[§&]#([0-9a-fA-F]{6}))|([^§&]+)/g;

  let currentColor = '#FFFFFF';
  let bold = false;
  let italic = false;
  let underlined = false;
  let strikethrough = false;

  let match: RegExpExecArray | null;

  while ((match = regex.exec(normalized)) !== null) {
    const code = match[1]?.toLowerCase();
    const hexColor = match[2];
    const text = match[3];

    if (hexColor) {
      currentColor = `#${hexColor}`;
    } else if (code) {
      if (COLOR_MAP[code]) {
        currentColor = COLOR_MAP[code];
        bold = false;
        italic = false;
        underlined = false;
        strikethrough = false;
      } else if (code === 'l') {
        bold = true;
      } else if (code === 'm') {
        strikethrough = true;
      } else if (code === 'n') {
        underlined = true;
      } else if (code === 'o') {
        italic = true;
      } else if (code === 'r') {
        currentColor = '#FFFFFF';
        bold = false;
        italic = false;
        underlined = false;
        strikethrough = false;
      }
    } else if (text) {
      pieces.push({
        text,
        color: currentColor,
        bold,
        italic,
        underlined,
        strikethrough,
      });
    }
  }

  if (pieces.length === 0 && input) {
    pieces.push({ text: input, color: '#FFFFFF' });
  }

  return pieces;
}

export function unwrapNbt(nbt: any): any {
  if (!nbt || typeof nbt !== 'object') return nbt;

  // Handle prismarine-nbt compound { type: "compound", value: { ... } }
  if (nbt.type === 'compound' && nbt.value && typeof nbt.value === 'object') {
    const result: Record<string, any> = {};
    for (const key of Object.keys(nbt.value)) {
      const field = nbt.value[key];
      const targetKey = key === '' ? 'text' : key;
      result[targetKey] = unwrapNbt(field);
    }
    return result;
  }

  // Handle prismarine-nbt list { type: "list", value: { type: "compound", value: [...] } } or value: [...]
  if (nbt.type === 'list' && nbt.value) {
    if (Array.isArray(nbt.value)) {
      return nbt.value.map(unwrapNbt);
    }
    if (nbt.value && typeof nbt.value === 'object' && Array.isArray(nbt.value.value)) {
      return nbt.value.value.map(unwrapNbt);
    }
    return unwrapNbt(nbt.value);
  }

  // Handle primitive NBT tags like { type: "string" | "byte" | "int", value: val }
  if (nbt.type && nbt.value !== undefined) {
    if (nbt.type === 'byte') {
      return nbt.value === 1 ? true : nbt.value === 0 ? false : nbt.value;
    }
    return unwrapNbt(nbt.value);
  }

  // Handle array
  if (Array.isArray(nbt)) {
    return nbt.map(unwrapNbt);
  }

  // Handle standard object
  const res: Record<string, any> = {};
  for (const k of Object.keys(nbt)) {
    res[k] = unwrapNbt(nbt[k]);
  }
  return res;
}

export function parseMcJsonMessage(jsonMsg: any): ChatPiece[] {
  if (!jsonMsg) return [];
  const unwrapped = unwrapNbt(jsonMsg);
  const pieces: ChatPiece[] = [];

  function processComponent(
    comp: any,
    inheritedColor?: string,
    inheritedBold?: boolean,
    inheritedItalic?: boolean,
    inheritedUnderline?: boolean,
    inheritedStrike?: boolean
  ) {
    if (!comp) return;

    if (typeof comp === 'string' || typeof comp === 'number') {
      const parsed = parseMcColorCodes(String(comp));
      for (const piece of parsed) {
        pieces.push({
          ...piece,
          color: piece.color !== '#FFFFFF' ? piece.color : inheritedColor || piece.color,
          bold: piece.bold || inheritedBold,
          italic: piece.italic || inheritedItalic,
          underlined: piece.underlined || inheritedUnderline,
          strikethrough: piece.strikethrough || inheritedStrike,
        });
      }
      return;
    }

    if (Array.isArray(comp)) {
      for (const item of comp) {
        processComponent(
          item,
          inheritedColor,
          inheritedBold,
          inheritedItalic,
          inheritedUnderline,
          inheritedStrike
        );
      }
      return;
    }

    const text = comp.text || comp.translate || '';
    let rawColor = comp.color || inheritedColor || '#FFFFFF';
    let color = rawColor;

    if (COLOR_MAP[rawColor.toLowerCase()]) {
      color = COLOR_MAP[rawColor.toLowerCase()];
    } else if (rawColor.startsWith('#')) {
      color = rawColor;
    } else {
      color = '#FFFFFF';
    }

    const isBold = comp.bold !== undefined ? !!comp.bold : inheritedBold;
    const isItalic = comp.italic !== undefined ? !!comp.italic : inheritedItalic;
    const isUnderlined = comp.underlined !== undefined ? !!comp.underlined : inheritedUnderline;
    const isStrikethrough = comp.strikethrough !== undefined ? !!comp.strikethrough : inheritedStrike;

    if (text) {
      const subPieces = parseMcColorCodes(text);
      for (const sp of subPieces) {
        pieces.push({
          text: sp.text,
          color: sp.color !== '#FFFFFF' ? sp.color : color,
          bold: sp.bold || isBold,
          italic: sp.italic || isItalic,
          underlined: sp.underlined || isUnderlined,
          strikethrough: sp.strikethrough || isStrikethrough,
        });
      }
    }

    if (comp.extra && Array.isArray(comp.extra)) {
      for (const extraItem of comp.extra) {
        processComponent(
          extraItem,
          color,
          isBold,
          isItalic,
          isUnderlined,
          isStrikethrough
        );
      }
    }
  }

  processComponent(unwrapped);
  return pieces;
}

export function parseMcLogMessage(
  log: { text: string; json?: any },
  isDebugMode: boolean = false
): ChatPiece[] {
  if (isDebugMode) {
    const rawText = log.text || (typeof log.json === 'string' ? log.json : JSON.stringify(log.json));
    return [{ text: rawText, color: '#94A3B8' }];
  }

  // Debug OFF: Format and style cleanly
  if (log.json) {
    return parseMcJsonMessage(log.json);
  }

  const text = log.text || '';

  // Check if text contains embedded JSON/NBT compound (e.g. "Bot stopped: Disconnected (Kicked: {"type":"compound"...})")
  const jsonMatch = text.match(/^(.*?)(\{[\s\S]*\}|\[[\s\S]*\])(.*?)$/);
  if (jsonMatch) {
    const prefix = jsonMatch[1];
    const jsonStr = jsonMatch[2];
    const suffix = jsonMatch[3];

    try {
      const parsedJson = JSON.parse(jsonStr);
      const unwrapped = unwrapNbt(parsedJson);
      const parsedPieces = parseMcJsonMessage(unwrapped);

      const pieces: ChatPiece[] = [];
      if (prefix) {
        pieces.push(...parseMcColorCodes(prefix));
      }
      pieces.push(...parsedPieces);
      if (suffix) {
        pieces.push(...parseMcColorCodes(suffix));
      }
      return pieces;
    } catch (e) {
      // If JSON parsing fails, fallback to normal color code parsing
    }
  }

  return parseMcColorCodes(text);
}

export function extractPlainTextFromMcJson(input: any): string {
  if (!input) return '';

  if (typeof input === 'string') {
    // Try to parse JSON if string starts with { or [
    const trimmed = input.trim();
    if (trimmed.startsWith('{') || trimmed.startsWith('[')) {
      try {
        const parsed = JSON.parse(trimmed);
        return extractPlainTextFromMcJson(parsed);
      } catch (e) {
        // Fallback to strip § and & color codes
      }
    }
    return input.replace(/[§&][0-9a-fk-or]/gi, '').replace(/[§&]#[0-9a-fA-F]{6}/gi, '').trim();
  }

  let result = '';

  if (typeof input === 'object') {
    if (input.text) result += input.text;
    if (input.translate) result += input.translate;

    if (Array.isArray(input.extra)) {
      for (const extraItem of input.extra) {
        result += extractPlainTextFromMcJson(extraItem);
      }
    }

    if (Array.isArray(input)) {
      for (const item of input) {
        result += extractPlainTextFromMcJson(item);
      }
    }
  }

  return result.replace(/\n+/g, ' ').replace(/\s+/g, ' ').trim();
}

