           }
           return prop;
         });

         if (innerModified) {
           line = `${indent}${key} = { ${fixedProps.join(', ')} }${comment}`;
           fixCount++;
           logs.push(`Dòng ${i + 1}: Sửa dấu ngoặc kép cho đối tượng ${key} -> { ${fixedProps.join(', ')} }`);
         }
       }
       repairedLines.push(line);
       continue;
     }

     // 3. Fix Unquoted Strings or TOML Array Keys e.g. ChatBot, Matches_File = matches.ini, ServerIP = 127.0.0.1
     const kvMatch = line.match(/^(\s*)([a-zA-Z0-9_\-.]+)\s*=\s*(.*)$/);
     if (kvMatch) {
       const indent = kvMatch[1];
       const key = kvMatch[2].trim();
       let valAndComment = kvMatch[3].trim();

       // Separate inline comment
       let val = valAndComment;
       let comment = '';
       const hashIdx = valAndComment.indexOf('#');
       const semiIdx = valAndComment.indexOf(';');
       const commentIdx = hashIdx !== -1 && semiIdx !== -1 ? Math.min(hashIdx, semiIdx) : (hashIdx !== -1 ? hashIdx : semiIdx);

       if (commentIdx !== -1) {
         val = valAndComment.slice(0, commentIdx).trim();
         comment = ' ' + valAndComment.slice(commentIdx).trim();
       }

       // Check if key is a known TOML Array property (e.g. ChatBot, Bots, BotOwners, Matches, Excludes)
       const ARRAY_KEYS = ['chatbot', 'bots', 'botowners', 'matches', 'excludes', 'packetdebugexclusions', 'entites_list', 'script', 'commands'];
       const isArrayKey = ARRAY_KEYS.includes(key.toLowerCase());

       if (isArrayKey) {
         // If it's already formatted as a TOML array e.g. [ "AutoRespond" ], do not touch
         if (val.startsWith('[') && val.endsWith(']')) {
           repairedLines.push(line);
           continue;
         }

         // Format unquoted list/string into a TOML Array e.g. ChatBot = [ "AutoRespond" ]
         const items = val
           .split(',')
           .map((s) => s.trim().replace(/^["']|["']$/g, ''))
           .filter(Boolean);

         const newArrVal = items.length > 0 ? `[ ${items.map((it) => `"${it}"`).join(', ')} ]` : '[ ]';
         line = `${indent}${key} = ${newArrVal}${comment}`;
         fixCount++;
         logs.push(`Dòng ${i + 1}: Chuyển ${key} thành Mảng TOML (Array) chuẩn -> ${newArrVal}`);
         repairedLines.push(line);
         continue;
       }

       // Check if general string value needs quoting
       if (
         val &&
         !val.startsWith('"') &&
         !val.startsWith("'") &&
         !val.startsWith('[') &&
         !val.startsWith('{') &&
         val.toLowerCase() !== 'true' &&
         val.toLowerCase() !== 'false'
       ) {
         // Check if pure integer or single decimal float (e.g. 25565 or 1.0)
         const isPureNumber = !isNaN(Number(val)) && !val.includes('..') && !/^[0-9]+\.[0-9]+\.[0-9]+/.test(val);

         if (!isPureNumber) {
           const newVal = `"${val}"`;
           line = `${indent}${key} = ${newVal}${comment}`;
           fixCount++;
           logs.push(`Dòng ${i + 1}: Thêm dấu ngoặc kép cho ${key} = ${newVal}`);
         }
       }

       // Escape unescaped backslashes inside already-quoted values (fixes "\\. invalid escape sequence")
       if (val.startsWith('"') && val.endsWith('"') && val.includes('\\')) {
         const safeVal = escapeBackslashes(val);
         if (safeVal !== val) {
           line = `${indent}${key} = ${safeVal}${comment}`;
           fixCount++;
           logs.push(`Dòng ${i + 1}: Escape dấu gạch chéo ngược trong ${key} -> ${safeVal}`);
         }
       }
     }

     repairedLines.push(line);
   }

   return {
     repairedIni: repairedLines.join('\n'),
     fixCount,
     logs,
   };
 }

