 // Auto-repair common syntax errors in MinecraftClient.ini
 export function fixAndSanitizeIniContent(rawIni: string): INIRepairResult {
   const lines = rawIni.split(/\r?\n/);
   const repairedLines: string[] = [];
   let fixCount = 0;
   const logs: string[] = [];

   /** Escape unescaped backslashes inside a quoted value so MCC's ini parser never breaks
-      (fixes "Found an invalid escape sequence '\\.'" errors from pasted Windows paths etc.) */
+      (fixes "Found an invalid escape sequence '\\.'" errors from pasted Windows paths etc.).
+      Already-escaped pairs ("\\") are left untouched so the fixer never double-escapes. */
   const escapeBackslashes = (quoted: string): string => {
     if (!quoted.includes('\\')) return quoted;
     const quoteChar = quoted[0];
     const inner = quoted.slice(1, -1);
-    const escaped = inner.replace(/\\(?!\\)/g, '\\\\');
+    let escaped = '';
+    for (let i = 0; i < inner.length; i++) {
+      const c = inner[i];
+      if (c === '\\') {
+        if (inner[i + 1] === '\\') {
+          escaped += '\\\\';
+          i++;
+        } else {
+          escaped += '\\\\';
+        }
+      } else {
+        escaped += c;
+      }
+    }
     return quoteChar + escaped + quoteChar;
   };

   for (let i = 0; i < lines.length; i++) {
     let line = lines[i];
     const trimmed = line.trim();

     // Skip empty lines or pure comment lines
     if (!trimmed || trimmed.startsWith('#') || trimmed.startsWith(';')) {
       repairedLines.push(line);
       continue;
     }

     // 1. Fix Section Headers e.g. [ChatBot.AutoRespond (missing ']') or [ChatBot.AutoRespond.]
     if (trimmed.startsWith('[')) {
       // Check if missing closing bracket
       if (!trimmed.includes(']')) {
         let name = trimmed.replace(/^\[+/, '').trim();
         name = name.replace(/\.+$|^\.+/g, ''); // strip trailing or leading dots
         line = `[${name}]`;
         fixCount++;
         logs.push(`Dòng ${i + 1}: Thêm dấu ']' còn thiếu cho section header -> [${name}]`);
       } else {
         // Has both brackets, clean up extra dots inside or outside e.g. [ChatBot.AutoRespond.]
         const match = line.match(/^(\s*)\[+([^\]]+)\]+(\s*)$/);
         if (match) {
           const indent = match[1];
           let secName = match[2].trim();
           const cleanName = secName.replace(/^\.+|\.+$|(?<=\.)\.+/g, ''); // remove leading/trailing or double dots
           if (secName !== cleanName) {
             line = `${indent}[${cleanName}]`;
             fixCount++;
             logs.push(`Dòng ${i + 1}: Sửa tên section header -> [${cleanName}]`);
           }
         }
       }
       repairedLines.push(line);
       continue;
     }

     // 2. Fix Inline Object Syntax e.g. Server = { Host = 127.0.0.1, Port = 25565 } or Account = { Login = geasf }
     if (trimmed.includes('{') && trimmed.includes('}')) {
       const kvMatch = line.match(/^(\s*)([a-zA-Z0-9_\-.\s"']+)=\s*\{(.*)\}(\s*#.*)?$/);
       if (kvMatch) {
         const indent = kvMatch[1];
         const key = kvMatch[2].trim();
         const inner = kvMatch[3];
         const comment = kvMatch[4] || '';

         // Process inner properties e.g. Host = 127.0.0.1, Port = 25565
         const props = inner.split(',').map((p) => p.trim()).filter(Boolean);
         let innerModified = false;

         const fixedProps = props.map((prop) => {
           const propMatch = prop.match(/^([a-zA-Z0-9_\-]+)\s*=\s*(.*)$/);
           if (propMatch) {
             const pKey = propMatch[1].trim();
             let pVal = propMatch[2].trim();

             // Unquote erroneously quoted empty array strings e.g. Times = "[ ]"
             if (pVal === '"[ ]"' || pVal === "'[ ]'") {
               pVal = '[ ]';
               innerModified = true;
             } else if (
               !pVal.startsWith('"') &&
               !pVal.startsWith("'") &&
               !pVal.startsWith('[') &&
               pVal.toLowerCase() !== 'true' &&
               pVal.toLowerCase() !== 'false' &&
               isNaN(Number(pVal))
             ) {
               pVal = `"${pVal}"`;
               innerModified = true;
             }

             // Escape unescaped backslashes in quoted values (fixes "\\. invalid escape sequence")
             if (pVal.startsWith('"') && pVal.includes('\\')) {
               const safeVal = escapeBackslashes(pVal);
               if (safeVal !== pVal) {
                 pVal = safeVal;
                 innerModified = true;
               }
             }
             return `${pKey} = ${pVal}`;
           }
           return prop;
         });

         if (innerModified) {
           line = `${indent}${key} = { ${fixedProps.join(', ')} }${comment}`;
           fixCount++;
           logs.push(`Dòng ${i + 1}: Sửa dấu ngoặc kép cho đối tượng ${key} -> { ${fixedProps.join(', ')} }`);
         }
       }
       repairedLines.push(line);
       continue;
     }

     // 3. Fix Unquoted Strings or TOML Array Keys e.g. ChatBot, Matches_File = matches.ini, ServerIP = 127.0.0.1
     const kvMatch = line.match(/^(\s*)([a-zA-Z0-9_\-.]+)\s*=\s*(.*)$/);
     if (kvMatch) {
       const indent = kvMatch[1];
       const key = kvMatch[2].trim();
       let valAndComment = kvMatch[3].trim();

       // Separate inline comment
       let val = valAndComment;
       let comment = '';
       const hashIdx = valAndComment.indexOf('#');
       const semiIdx = valAndComment.indexOf(';');
       const commentIdx = hashIdx !== -1 && semiIdx !== -1 ? Math.min(hashIdx, semiIdx) : (hashIdx !== -1 ? hashIdx : semiIdx);

       if (commentIdx !== -1) {
         val = valAndComment.slice(0, commentIdx).trim();
         comment = ' ' + valAndComment.slice(commentIdx).trim();
       }

       // Check if key is a known TOML Array property (e.g. ChatBot, Bots, BotOwners, Matches, Excludes)
       const ARRAY_KEYS = ['chatbot', 'bots', 'botowners', 'matches', 'excludes', 'packetdebugexclusions', 'entites_list', 'script', 'commands'];
       const isArrayKey = ARRAY_KEYS.includes(key.toLowerCase());

       if (isArrayKey) {
         // If it's already formatted as a TOML array e.g. [ "AutoRespond" ], do not touch
         if (val.startsWith('[') && val.endsWith(']')) {
           repairedLines.push(line);
           continue;
         }

         // Format unquoted list/string into a TOML Array e.g. ChatBot = [ "AutoRespond" ]
         const items = val
           .split(',')
           .map((s) => s.trim().replace(/^["']|["']$/g, ''))
           .filter(Boolean);

         const newArrVal = items.length > 0 ? `[ ${items.map((it) => `"${it}"`).join(', ')} ]` : '[ ]';
         line = `${indent}${key} = ${newArrVal}${comment}`;
         fixCount++;
         logs.push(`Dòng ${i + 1}: Chuyển ${key} thành Mảng TOML (Array) chuẩn -> ${newArrVal}`);
         repairedLines.push(line);
         continue;
       }

       // Check if general string value needs quoting
       if (
         val &&
         !val.startsWith('"') &&
         !val.startsWith("'") &&
         !val.startsWith('[') &&
         !val.startsWith('{') &&
         val.toLowerCase() !== 'true' &&
         val.toLowerCase() !== 'false'
       ) {
         // Check if pure integer or single decimal float (e.g. 25565 or 1.0)
         const isPureNumber = !isNaN(Number(val)) && !val.includes('..') && !/^[0-9]+\.[0-9]+\.[0-9]+/.test(val);

         if (!isPureNumber) {
           const newVal = `"${val}"`;
           line = `${indent}${key} = ${newVal}${comment}`;
           fixCount++;
           logs.push(`Dòng ${i + 1}: Thêm dấu ngoặc kép cho ${key} = ${newVal}`);
         }
       }

       // Escape unescaped backslashes inside already-quoted values (fixes "\\. invalid escape sequence")
       if (val.startsWith('"') && val.endsWith('"') && val.includes('\\')) {
         const safeVal = escapeBackslashes(val);
         if (safeVal !== val) {
           line = `${indent}${key} = ${safeVal}${comment}`;
           fixCount++;
           logs.push(`Dòng ${i + 1}: Escape dấu gạch chéo ngược trong ${key} -> ${safeVal}`);
         }
       }
     }

     repairedLines.push(line);
   }

   return {
     repairedIni: repairedLines.join('\n'),
     fixCount,
     logs,
   };
 }

